# Propiedades que verificará el validador
Se verificará: `build(inst, rng)` devuelve una solución FACTIBLE y es determinista dada la semilla del rng, también en una instancia de tamaño realista. Comprueba la factibilidad con `problem.is_feasible(sol)` dentro de `build` y repara antes de devolver. Factible significa: cada cliente exactamente una vez y cada ruta con carga <= capacidad. Con flota libre siempre puedes abrir otra ruta, así que la factibilidad es fácil; la calidad está en agrupar clientes cercanos.

Declara `"compatible_skeletons": ['SA', 'ILS', 'TS', 'VNS', 'GRASP', 'LNS_MIP', 'FIX_OPT', 'LOCAL_BRANCH', 'MIP_PERTURB']` salvo que el componente dependa de un esqueleto concreto (p.ej. use la temperatura de SA).

# Ejemplo de componente válido para OTRO problema (mochila 0/1), en el formato exacto requerido
```python
from random import Random

COMPONENT = {
    "name": "greedy_ratio_rcl",
    "slot": "constructor",
    "compatible_skeletons": ["SA", "ILS", "LNS_MIP"],
    "requires": [],
    "params": {"alpha": {"type": "float", "range": [0.05, 1.0]}},
}


class GreedyRatioRCL:
    """GRASP: ordena por valor/peso y elige al azar dentro de una lista restringida de tamaño alpha."""

    def __init__(self, alpha: float = 0.3):
        self.alpha = alpha

    def build(self, inst, rng: Random):
        remaining, taken = inst.capacity, [False] * inst.n
        candidates = list(range(inst.n))
        while candidates:
            candidates = [i for i in candidates if inst.weights[i] <= remaining]
            if not candidates:
                break
            candidates.sort(key=lambda i: inst.values[i] / inst.weights[i], reverse=True)
            choice = rng.choice(candidates[: max(1, int(len(candidates) * self.alpha))])
            taken[choice] = True
            remaining -= inst.weights[choice]
            candidates.remove(choice)
        return tuple(taken)


def build_component(problem, alpha: float = 0.3):
    return GreedyRatioRCL(alpha=alpha)
